describe("checkAndSwitchWorkspaceForGitBranch", () => {
  const wmillYaml = [
    "workspaces:",
    "  cm:",
    "    baseUrl: https://windmill.example.net/",
    "    gitBranch: main",
    "    workspaceId: cm",
  ].join("\n");

  function onBranch(branch: string) {
    __setFileSystem({
      [`${ROOT}/.git`]: __DIRECTORY,
      [`${ROOT}/.git/HEAD`]: `ref: refs/heads/${branch}\n`,
      [`${ROOT}/wmill.yaml`]: wmillYaml,
    });
  }

  it("loads wmill.yaml and switches for the current branch", async () => {
    onBranch("main");
    __resetConfiguration({
      currentWorkspace: "ir",
      additionalWorkspaces: [
        { name: "cm-prod", remote: REMOTE, workspaceId: "cm", token: "cm-token" },
      ],
    });

    const result = await checkAndSwitchWorkspaceForGitBranch(__outputChannel(), undefined);
    expect(result.switched).toBe(true);
    // The loaded config is handed back for caching
    expect(result.config).toEqual({
      cm: { baseUrl: REMOTE, gitBranch: "main", workspaceId: "cm" },
    });
  });

  it("uses the cached config instead of re-reading wmill.yaml", async () => {
    // Only .git exists: a reload would find no config and not switch
    __setFileSystem({
      [`${ROOT}/.git`]: __DIRECTORY,
      [`${ROOT}/.git/HEAD`]: "ref: refs/heads/main\n",
    });
    __resetConfiguration({
      currentWorkspace: "ir",
      additionalWorkspaces: [
        { name: "cm-prod", remote: REMOTE, workspaceId: "cm", token: "cm-token" },
      ],
    });

    const cached = { cm: { baseUrl: REMOTE, gitBranch: "main", workspaceId: "cm" } };
    const result = await checkAndSwitchWorkspaceForGitBranch(__outputChannel(), cached);
    expect(result.switched).toBe(true);
  });

  it("does nothing outside a git repository", async () => {
    __setFileSystem({ [`${ROOT}/wmill.yaml`]: wmillYaml });

    const channel = __outputChannel();
    expect(await checkAndSwitchWorkspaceForGitBranch(channel, undefined)).toEqual({
      switched: false,
    });
    expect(channel.lines).toContain("No git branch detected or not in a git repository");
  });

  it("does nothing without a workspace folder", async () => {
    onBranch("main");
    __setWorkspaceFolders([]);

    expect(await checkAndSwitchWorkspaceForGitBranch(__outputChannel(), undefined)).toEqual(
      { switched: false }
    );
  });

  it("reports when wmill.yaml has no workspaces section", async () => {
    __setFileSystem({
      [`${ROOT}/.git`]: __DIRECTORY,
      [`${ROOT}/.git/HEAD`]: "ref: refs/heads/main\n",
      [`${ROOT}/wmill.yaml`]: "defaultTs: bun",
    });

    const channel = __outputChannel();
    const result = await checkAndSwitchWorkspaceForGitBranch(channel, undefined);
    expect(result).toEqual({ switched: false, config: undefined });
    expect(channel.lines).toContain("No workspaces configuration found in wmill.yaml");
  });

  it("keeps the current workspace on an unconfigured branch", async () => {
    onBranch("dev");
    __resetConfiguration({
      currentWorkspace: "ir",
      additionalWorkspaces: [
        { name: "cm-prod", remote: REMOTE, workspaceId: "cm", token: "cm-token" },
      ],
    });

    const result = await checkAndSwitchWorkspaceForGitBranch(__outputChannel(), undefined);
    expect(result.switched).toBe(false);
    // The config is still cached for the next check
    expect(result.config).toBeDefined();
  });

  it("survives a wmill.yaml that is not valid YAML", async () => {
    jest.spyOn(console, "error").mockImplementation(() => undefined);
    __setFileSystem({
      [`${ROOT}/.git`]: __DIRECTORY,
      [`${ROOT}/.git/HEAD`]: "ref: refs/heads/main\n",
      [`${ROOT}/wmill.yaml`]: "workspaces:\n  cm:\n   baseUrl: [unclosed\n",
    });

    const channel = __outputChannel();
    const result = await checkAndSwitchWorkspaceForGitBranch(channel, undefined);
    expect(result).toEqual({ switched: false });
    expect(
      channel.lines.some((l: string) => l.includes("Error checking git branch"))
    ).toBe(true);
    jest.restoreAllMocks();
  });

  it("switches to the fork workspace on a fork branch", async () => {
    onBranch("wm-fork/main/abc");
    __resetConfiguration({
      currentWorkspace: "ir",
      additionalWorkspaces: [
        { name: "cm-prod", remote: REMOTE, workspaceId: "cm", token: "cm-token" },
      ],
    });

    const result = await checkAndSwitchWorkspaceForGitBranch(__outputChannel(), undefined);
    expect(result.switched).toBe(true);
  });
});

import {
  extractInlineScripts,
  newPathAssigner,
} from "windmill-utils-internal";
import { FlowModule } from "windmill-client";

/**
 * Helper to create a minimal FlowModule with an inline script.
 */
function makeInlineModule(
  id: string,
  language: string,
  content: string
): FlowModule {
  return {
    id,
    value: {
      type: "rawscript",
      language,
      content,
    },
  } as unknown as FlowModule;
}

describe("nonDottedPaths / skipInlineScriptSuffix", () => {
  describe("extractInlineScripts", () => {
    it("should use .inline_script. suffix by default", () => {
      const modules = [
        makeInlineModule("a", "bun", 'console.log("hello")'),
        makeInlineModule("b", "python3", 'print("hello")'),
      ];
      const result = extractInlineScripts(modules, {}, "/", "bun");
      expect(result).toEqual(
        expect.arrayContaining([
          expect.objectContaining({ path: "a.inline_script.ts" }),
          expect.objectContaining({ path: "b.inline_script.py" }),
        ])
      );
    });

    it("should use .inline_script. suffix when skipInlineScriptSuffix is false", () => {
      const modules = [
        makeInlineModule("a", "bun", 'console.log("hello")'),
      ];
      const result = extractInlineScripts(modules, {}, "/", "bun", undefined, {
        skipInlineScriptSuffix: false,
      });
      expect(result[0].path).toBe("a.inline_script.ts");
    });

    it("should NOT use .inline_script. suffix when skipInlineScriptSuffix is true", () => {
      const modules = [
        makeInlineModule("a", "bun", 'console.log("hello")'),
        makeInlineModule("b", "python3", 'print("hello")'),
      ];
      const result = extractInlineScripts(modules, {}, "/", "bun", undefined, {
        skipInlineScriptSuffix: true,
      });
      expect(result).toEqual(
        expect.arrayContaining([
          expect.objectContaining({ path: "a.ts" }),
          expect.objectContaining({ path: "b.py" }),
        ])
      );
    });

    it("should produce correct extensions regardless of suffix mode", () => {
      const modules1 = [
        makeInlineModule("x", "bun", "code"),
        makeInlineModule("y", "python3", "code"),
      ];
      const modules2 = [
        makeInlineModule("x", "bun", "code"),
        makeInlineModule("y", "python3", "code"),
      ];
      const withSuffix = extractInlineScripts(
        modules1,
        {},
        "/",
        "bun",
        undefined,
        { skipInlineScriptSuffix: false }
      );
      const withoutSuffix = extractInlineScripts(
        modules2,
        {},
        "/",
        "bun",
        undefined,
        { skipInlineScriptSuffix: true }
      );

      expect(withSuffix.some((s) => s.path.endsWith(".ts"))).toBe(true);
      expect(withSuffix.some((s) => s.path.endsWith(".py"))).toBe(true);
      expect(withoutSuffix.some((s) => s.path.endsWith(".ts"))).toBe(true);
      expect(withoutSuffix.some((s) => s.path.endsWith(".py"))).toBe(true);
    });

    it("should replace module content with !inline references matching file names", () => {
      const testModules: FlowModule[] = [
        makeInlineModule("step1", "bun", 'console.log("test")'),
      ];

      const result = extractInlineScripts(
        testModules,
        {},
        "/",
        "bun",
        undefined,
        { skipInlineScriptSuffix: true }
      );

      expect(result[0].path).toBe("step1.ts");

      // The module's content should have been replaced with !inline reference
      const module = testModules[0] as any;
      expect(module.value.content).toBe("!inline step1.ts");
    });

    it("should use .inline_script. in !inline references when suffix is not skipped", () => {
      const testModules: FlowModule[] = [
